style.css:
@-moz-document domain("slashdot.org") {
/* ---------- palette ----------
     base bg            #14181d
     elevated surface   #1c2128
     header/footer      #0d1117
     border subtle      #262c33   component #2d333b
     text primary       #e6edf3   body #c4cdd6   muted #8b949e
     link/accent        #5fb0e6   hover #9bd4ff
     Slashdot green      brand teal-green, adapted: #3ca58f surfaces / #6fd8be text
     score highlight     #6fd8be   score dimmed #8b949e
  */

  :root { color-scheme: dark; }

  html, body {
    background: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* base text + generic containers */
  body, .grid_24, #firehose, #slashboxes, #firehoselist,
  article.fhitem, .fhitem, .body, header, footer, section, aside, .novote, div {
    color: #c4cdd6;
  }

  /* soften every light border */
  * { border-color: #262c33 !important; }

  /* ---------- links ---------- */
  a, a:link, a:visited { color: #5fb0e6 !important; }
  a:hover { color: #9bd4ff !important; }

  /* ---------- masthead / logo ---------- */
  /* keep the Slashdot SVG logo visible on dark */
  #logo, .logo, h1#slashdot_org, #slashdot_org { filter: none; }

  /* top navigation / masthead — keep the iconic Slashdot green identity,
     deepened so it sits on the dark palette (the two green bars) */
  .nav-wrap, #main-top-nav-wrapper, nav.nav-user, nav.nav-primary, .nav-primary,
  #topbar, #user-bar, .menu {
    background: #0c3433 !important;
    color: #e6edf3 !important;
  }
  .nav-secondary-wrap, nav.nav-secondary {
    background: #0a2826 !important;
    color: #cdd9d6 !important;
  }
  /* all links inside both masthead bars: light + readable on the deep green */
  .nav-wrap a, #main-top-nav-wrapper a, .nav-user a, .nav-secondary-wrap a,
  .nav-secondary a, .nav-primary a, #user-bar a,
  .nav-wrap span, .nav-secondary-wrap .nav-label,
  .nav-wrap .nav-label { color: #e6edf3 !important; }
  .nav-wrap a:hover, .nav-secondary-wrap a:hover, .nav-primary a:hover { color: #9be7d6 !important; }
  /* "or" / "Topics:" / "Follow us:" small labels */
  .nav-label, li.nav-label { color: #9fc7c0 !important; }

  /* ---------- story listing cards (firehose) ---------- */
  article.fhitem, .fhitem,
  article.fhitem-story, article.deals-rail, article.nosort, #slashdot_deals {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  /* the iconic green story-title bar — keep the Slashdot green identity, tuned for dark.
     h2.firehose is the firehose/user-submission title bar (separate from h2.story);
     it ships a light-grey #ececec→#cdcdcd gradient with black text — the green
     `background` shorthand here also clears that gradient. */
  h2.story, .story, .fhtitle, article .story,
  h2.firehose, article header h2.firehose {
    background: #14463d !important;
    color: #e6edf3 !important;
    border-color: #1d5d50 !important;
  }
  h2.story a, .story a, .story-title, .story-title a,
  h2.story span, .story span.no,
  h2.firehose a, h2.firehose span.story-title { color: #e6edf3 !important; }
  /* source link inside the green bar */
  a.story-sourcelnk, .story-sourcelnk { color: #8fd9c8 !important; }

  /* comment-count bubble */
  .comment-bubble { background: #0d1117 !important; color: #e6edf3 !important; }
  .comment-bubble a { color: #e6edf3 !important; }

  /* story details bar (views / byline / dept / time) */
  .details, .story-details, div.details {
    background: #161b22 !important;
    color: #9aa4ad !important;
    border-color: #262c33 !important;
  }
  .story-views, .sodify, .story-byline, .dept-text, .story-details,
  time, span.otherdetails, .by, .byby, .uid, .writes, small {
    color: #9aa4ad !important;
  }
  .story-byline a, .details a, .by a { color: #5fb0e6 !important; }

  /* topic / type icons + popularity beaker — keep popularity red semantic but soften */
  .icon-beaker.pop1, span.icon-beaker { color: #e06c6c !important; }
  .type, .topic, .sd-info-block, .sd-key-firehose-id { color: #8b949e !important; }

  /* story body copy */
  .body, div.body, .p, div.p, .intro, .article .body {
    color: #c4cdd6 !important;
    background: transparent !important;
  }

  /* ---------- comment thread (the key surface) ---------- */
  #comments, #commentwrap, .commentwrap, #commentlisting,
  .comment, li.comment, .cw, .commentBox, .commentstatus, .commentSub {
    background: transparent !important;
    color: #c4cdd6 !important;
  }

  /* each comment wrapper sits on an elevated card */
  .cw, div.cw {
    background: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* comment title bar — green identity, white-ish title */
  .commentTop, div.commentTop {
    background: transparent !important;
  }
  .commentTop h4, .comment h4, .title h4 {
    background: #14463d !important;
    color: #e6edf3 !important;
  }
  .commentTop h4 a, .comment h4 a, .title h4 a { color: #e6edf3 !important; }

  /* score label: highlighted (white on green) vs dimmed (gray) */
  .score, span.score { color: #e6edf3 !important; }
  .score a, .score .opt { color: #e6edf3 !important; }
  /* keep mod-label readability inside the green bar */
  .commentTop h4 .score, .commentTop h4 .score a, .commentTop h4 .score .opt {
    color: #cfeee4 !important;
  }

  /* comment details / metadata line (was light-gray bg) */
  .details, div.details, .comment .details {
    background: #161b22 !important;
    color: #9aa4ad !important;
    border-color: #262c33 !important;
  }
  .comment .by, .comment .uid, .comment .otherdetails,
  .comment .writes, .comment .byby, .comment time { color: #9aa4ad !important; }
  .comment .by a, .comment .uid a { color: #5fb0e6 !important; }

  /* comment body text */
  .commentBody, div.commentBody, .commentBody p, .commentBody div {
    color: #c4cdd6 !important;
    background: transparent !important;
  }

  /* reply / parent / share controls */
  a.btn.link, .commentSub a, .menu a, a.reply {
    color: #6fd8be !important;
  }
  a.btn.link:hover, .commentSub a:hover { color: #9bead5 !important; }

  /* share popover — make opaque dark (was translucent light) */
  .comment_share, .comment_share.sharethis-0, span.au {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .comment_share a, .slashpop { color: #5fb0e6 !important; }

  /* moderation / quoted text / code inside comments */
  .commentBody blockquote, blockquote, .quote {
    background: #161b22 !important;
    border-left: 3px solid #2d333b !important;
    color: #c4cdd6 !important;
  }
  .commentBody code, .commentBody pre, code, pre, tt {
    background: #0d1117 !important;
    color: #a5d6ff !important;
    border-color: #2d333b !important;
  }
  .commentBody i, .commentBody em { color: #c4cdd6 !important; }

  /* comment controls box / display options / threshold */
  .commentControlBox, #display-options, #commentControlBox,
  .ccw-score-label, .morelink, .commentControl {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .ccw-score-label, .ccw-score-label * { color: #c4cdd6 !important; }
  .morelink, .morelink a { color: #5fb0e6 !important; }

  /* comment-threshold slider (#ccw widget): the Full/Abbreviated/Hidden zone
     panels ship a light→white gradient (the "Hidden" zone is pure #fff) and the
     thumb-corner .slant triangles are light grey — all audit-blind (short/nested,
     colored from a cross-origin sheet via two-id !important rules). Remap to a
     teal→dark scale that keeps the zone distinction on the dark green bar. */
  #ccw-body #ccw-full-panel, #ccw #ccw-full-panel { background-color: #3ca58f !important; }
  #ccw-body #ccw-abbr-panel, #ccw #ccw-abbr-panel { background-color: #27645a !important; }
  #ccw-body #ccw-hide-panel, #ccw #ccw-hide-panel { background-color: #2d333b !important; }
  #ccw .slant, #commentwrap .slant { background-color: #1c2128 !important; }

  /* ---------- sidebars / boxes (Firehose / Popular / Polls) ---------- */
  .block, .slashbox, aside.block, #links-sidebar, #slashboxes > div {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .boxhead, .block .title, .blockTitle, h3.title, h4.title,
  header#slashdot_deals-title, header#poll-title, header#mostdiscussed-title,
  header#srandblock-title, #slashboxes header, .block > header, aside header {
    background: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  #slashboxes header, #slashboxes header *, .block > header,
  .block > header * { color: #e6edf3 !important; }
  #slashboxes header a, .block > header a { color: #9bd4ff !important; }

  /* user profile bio card (#user_bio renders on #e6e6e6 → bio text would land on light) */
  article#user_bio, #user_bio {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  #user_bio a { color: #5fb0e6 !important; }

  /* user-page comment/submission list tables (~/comments) ship a white table
     background; the td cells get darkened by the neutralizer but the header
     row's <th> cells are transparent → the white leaks through as a bright strip
     (audit-blind: the th itself scans transparent). Darken the table + header. */
  table.data, table.listComments, table.data.listComments {
    background-color: #14181d !important;
  }
  table.data th, table.listComments th {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  table.data td, table.listComments td { border-color: #262c33 !important; }

  /* ---------- search / filter / inputs ---------- */
  input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], input[name="fhfilter"], textarea, select, #search input {
    background: #0d1117 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
    /* header search input draws a light (#f5f5f5) inset box-shadow that paints
       a silvery fill our background can't cover; appearance:auto adds native chrome */
    box-shadow: none !important;
    -webkit-appearance: none !important;
    appearance: none !important;
  }
  input[type="text"]::placeholder, input[type="search"]::placeholder,
  input[name="fhfilter"]::placeholder, textarea::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }
  /* buttons */
  input[type="submit"], input[type="button"], button, .btn, a.button {
    background: #21262d !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="submit"]:hover, button:hover, .btn:hover { background: #2d333b !important; }

  /* ---------- story submission form ---------- */
  /* header + subtitle were near-black (#2e2e2e / #676767) on the dark bg */
  .sd-form-header, .sd-brand-color { color: #6fd8be !important; }
  #form-wrapper hgroup p, #form-wrapper > hgroup > p { color: #9aa4ad !important; }
  /* the "You must be logged in…" notice well rendered on #f1f1f1 */
  .sd-well, p.sd-well {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .sd-well a { color: #5fb0e6 !important; }

  /* ---------- footer ---------- */
  footer#fhft, #fhft, footer#ft, #ft {
    background: #0d1117 !important;
    background-image: none !important;
    color: #9aa4ad !important;
    border-color: #262c33 !important;
  }
  footer a, #fhft a, #ft a { color: #5fb0e6 !important; }

  /* ---------- modals / overlays ---------- */
  .modal-box, #modal_box, #modal-box, .modal {
    background: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* dimmed / abbreviated (low-score) comments — keep them muted but legible
     (site dims these to #7d7d7d via an id-scoped rule, so match its specificity) */
  #commentlisting .oneline .commentBody,
  #commentlisting .oneline .commentBody p,
  #commentlisting .oneline .commentBody div,
  .comment.oneline .commentBody, .oneline .commentBody,
  .oneline .commentBody *, li.comment.oneline .commentBody {
    color: #9aa4ad !important;
  }
  #commentlisting .oneline .commentBody a,
  .oneline .commentBody a { color: #5fb0e6 !important; }

  /* comment score-selector widget + "You may like" header bar (light-grey #e1e1e1) */
  .grid_3, .sc, span.sc, h3, .ccwa, .ccwb, .tag-menu-admin, menu#tag-menu,
  menu#feedback-menu, .nf, input.fno {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .grid_3 a, .sc a, h3 a, .ccwa a, .ccwb a { color: #5fb0e6 !important; }

  /* ---------- generic light-surface neutralizer ---------- */
  /* native-ad / newsletter / "you may like" / comment-filter sections render
     on a hardcoded white or light-grey bg → darken to the base */
  section, section.grid_24, .ad-blocked-newsletter, .ntv-preview-img-wrapper,
  .sticky-cta, .sticky-wrapper, .sticky-left, .sticky-gradient,
  label, td, .thisday-yr, .commentControlBox, .a2 {
    background-color: #14181d !important;
  }
  section.bq, .bq, blockquote.msg, blockquote,
  .bq p, blockquote.msg p, section.bq p {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
  }
  /* the fortune / quote text + any leftover black body copy on dark */
  .bq *, blockquote.msg *, .msg, td, label, .legend, h3 {
    color: #c4cdd6 !important;
  }
  .thisday-yr { background-color: #0a2826 !important; color: #cdd9d6 !important; }

  /* comment-filter / "Comments Filter:" bar + its links */
  .commentControlBox, .commentControlBox *, #commentControlBox,
  .legend, .legend * { color: #c4cdd6 !important; }
  .commentControlBox a, .legend a { color: #5fb0e6 !important; }

  /* poll cards (More Polls list) — the vote-count + byline footer rows render
     on a hardcoded light-grey (#f2f2f2) with dark (#4d4d4d) text */
  .info-meta, .info-byline, .info-meta *, .info-byline * {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .info-meta a, .info-byline a { color: #5fb0e6 !important; }

  /* poll RESULT bars (after voting): the unfilled track ships a hardcoded light
     grey (#e1e1e1) — audit-blind (only ~20px tall). Darken the track; keep the
     orange vote fill (brand semantic) and make the overflow label text legible
     on both the orange fill and the dark track. */
  .poll-bar-bg { background-color: #21262d !important; }
  .poll-bar-text { color: #e6edf3 !important; }

  /* ---------- brand / semantic buttons (keep their color, fix text) ---------- */
  .btn-success, a.btn-success, .nel-button, .btn-polls, button.btn-polls,
  .btn-primary, input.button {
    color: #ffffff !important;
  }
  /* prev/next pager buttons sat on white */
  .prevnextbutdis, .prevnextbutact, .pad-btns a {
    background: #21262d !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }

  /* floating sticky-CTA banner — opaque dark, readable text */
  .sticky-cta, .sticky-cta *, .sticky-wrapper, .sticky-wrapper * {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
  .sticky-cta a, .sticky-wrapper a { color: #5fb0e6 !important; }

  /* native-ad "Sponsored / Featured Content" label — darken its brown/orange chip
     (Nativo classes: ntv-sponsored-disclaimer + dynamic-suffix ntv_link… link) */
  .ntv-ad-label, .ntv-sponsored, .nel-sponsored, .ntv-sponsored-disclaimer,
  span.sponsored, .sponsored-label, a[class*="ntv_link"] {
    background-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  .ntv-sponsored-disclaimer a, a[class*="ntv_link"] { color: #9bd4ff !important; }

  /* selected pager / tab list-items (load-more-comments, Related Links, All)
     render with a hardcoded white highlight → make them a dark active state */
  li.fleft, li.fleft.selected, ul.fleft li, nav ul li.selected,
  .btmrel, a.btmrel, li.btmrel, .filter-firehose li.selected {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  li.fleft a, li.fleft.selected a, .btmrel a, a.btmrel,
  .filter-firehose li.selected a, nav ul li.selected a {
    color: #9bd4ff !important;
  }
  /* the "Get N More Comments" button */
  #more_comments_button, .nbutton, span.nbutton {
    background-color: #21262d !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }

  /* prev/next page links sitting on the light-grey article footer band */
  .grid_24.f a, aside.st a, .st .links a { color: #9bd4ff !important; }

  /* active comment-filter tab ("All") — white highlight → dark active state */
  #comments li.active, .commentControlBox li.active, .filter-firehose li.active,
  ul.fleft li.active, li.active {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }
  #comments li.active a, .commentControlBox li.active a,
  li.active a { color: #9bd4ff !important; }

  /* sidebar topic-list nav header bar (#ccc) + its prev/next links */
  .tlnav, h5.tlnav, .tlnav-head {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  .tlnav a, h5.tlnav a { color: #9bd4ff !important; }
}
